$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-cards-f1.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},8500);
try{
const arr=await(await fetch('http://127.0.0.1:17447/json/list')).json();
const tab=arr.find(x=>x.id==='5BE7D591DA96F1CAFD3416FF88E7DE17');
if(!tab)throw Error('TARGET_MISSING');
const w=new WebSocket(tab.webSocketDebuggerUrl);
w.addEventListener('open',()=>w.send(JSON.stringify({id:13,method:'Runtime.evaluate',params:{expression:"(()=>Array.from(document.querySelectorAll('[data-marker=\"item\"]')).slice(0,35).map((e,i)=>{const h=e.querySelector('h3');const p=e.querySelector('[data-marker=\"item-price\"]')||e.querySelector('[itemprop=\"price\"]');const a=h?.closest('a[href]')||e.querySelector('a[href]');return {i,name:h?.textContent?.trim().slice(0,100)||'',price:p?.textContent?.trim().slice(0,55)||'',snippet:(e.textContent||'').replace(/\\s+/g,' ').slice(0,230),link:a?.href?new URL(a.href).origin+new URL(a.href).pathname:''};}))()",returnByValue:true}})),{once:true});
w.addEventListener('message',ev=>{const v=JSON.parse(ev.data);if(v.id===13){console.log(JSON.stringify(v.result?.result?.value||{error:v.result?.exceptionDetails?.text||v.error?.message||'EMPTY'}));process.exit(0)}});
w.addEventListener('error',()=>{console.log(JSON.stringify({error:'WS_ERROR'}));process.exit(0)},{once:true})
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,120)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
} finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
